#include "diagnostics.h"
#include "grammar.h"
#include "markup.h"
#include "recognizer.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int read_file(const char *path, char **data, size_t *length)
{
    FILE *file = fopen(path, "rb");
    long size;
    size_t got;
    char *buffer;
    if (file == NULL)
        return -1;
    if (fseek(file, 0, SEEK_END) != 0) {
        fclose(file);
        return -1;
    }
    size = ftell(file);
    if (size < 0 || fseek(file, 0, SEEK_SET) != 0) {
        fclose(file);
        return -1;
    }
    buffer = (char *)malloc((size_t)size + 1);
    if (buffer == NULL) {
        fclose(file);
        return -1;
    }
    got = fread(buffer, 1, (size_t)size, file);
    fclose(file);
    if (got != (size_t)size) {
        free(buffer);
        return -1;
    }
    buffer[got] = '\0';
    *data = buffer;
    *length = got;
    return 0;
}

static void print_grammar_error(const char *what, const Diagnostic *diagnostic)
{
    if (diagnostic->present)
        (void)fprintf(stdout, "GRAMMAR_ERROR %s offset=%zu line=%zu column=%zu %s\n",
                      what, diagnostic->loc.offset, diagnostic->loc.line,
                      diagnostic->loc.column, diagnostic->message);
    else
        (void)fprintf(stdout, "GRAMMAR_ERROR %s\n", what);
}

static Location end_location(const char *source, size_t length)
{
    size_t i;
    Location loc = {length, 1, 1};
    for (i = 0; i < length; i++) {
        if (source[i] == '\n') {
            loc.line++;
            loc.column = 1;
        } else {
            loc.column++;
        }
    }
    return loc;
}

int main(int argc, char **argv)
{
    const char *grammar_path = NULL;
    const char *input_path = NULL;
    const char *start_name = NULL;
    int stats = 0;
    char *grammar_source = NULL;
    char *input_source = NULL;
    size_t grammar_length = 0;
    size_t input_length = 0;
    Grammar grammar;
    Markup markup;
    Diagnostic diagnostic;
    Recognition recognition;
    int i;
    int status;
    memset(&diagnostic, 0, sizeof(diagnostic));
    if (argc < 5) {
        print_grammar_error("usage: bin/pbnfc --grammar PATH --input PATH [--start NAME] [--stats]", &diagnostic);
        return 2;
    }
    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--grammar") == 0 && i + 1 < argc)
            grammar_path = argv[++i];
        else if (strcmp(argv[i], "--input") == 0 && i + 1 < argc)
            input_path = argv[++i];
        else if (strcmp(argv[i], "--start") == 0 && i + 1 < argc)
            start_name = argv[++i];
        else if (strcmp(argv[i], "--stats") == 0)
            stats = 1;
        else {
            print_grammar_error("invalid command line", &diagnostic);
            return 2;
        }
    }
    if (grammar_path == NULL || input_path == NULL) {
        print_grammar_error("--grammar and --input are required", &diagnostic);
        return 2;
    }
    if (read_file(grammar_path, &grammar_source, &grammar_length) != 0) {
        (void)fprintf(stdout, "GRAMMAR_ERROR cannot read grammar: %s\n", grammar_path);
        return 2;
    }
    if (read_file(input_path, &input_source, &input_length) != 0) {
        free(grammar_source);
        (void)fprintf(stdout, "GRAMMAR_ERROR cannot read input: %s\n", input_path);
        return 2;
    }
    if (grammar_parse(grammar_source, grammar_length, &grammar, &diagnostic) != 0) {
        print_grammar_error("grammar", &diagnostic);
        free(grammar_source);
        free(input_source);
        return 2;
    }
    if (start_name != NULL && grammar_set_start(&grammar, start_name, &diagnostic) != 0) {
        print_grammar_error("grammar", &diagnostic);
        grammar_free(&grammar);
        free(grammar_source);
        free(input_source);
        return 2;
    }
    if (markup_lex(input_source, input_length, &markup, &diagnostic) != 0) {
        print_grammar_error("markup", &diagnostic);
        grammar_free(&grammar);
        free(grammar_source);
        free(input_source);
        return 2;
    }
    status = recognize(&grammar, &markup, &recognition);
    if (status != 0) {
        (void)fprintf(stdout, "GRAMMAR_ERROR recognizer failure\n");
        markup_free(&markup);
        grammar_free(&grammar);
        free(grammar_source);
        free(input_source);
        return 2;
    }
    if (recognition.accepted) {
        (void)fprintf(stdout, "ACCEPT tokens=%zu", markup.count);
        if (stats) {
            (void)fprintf(stdout, " workers=8 active_workers=8 rounds=%zu tasks=", recognition.rounds);
            for (i = 0; i < 8; i++)
                (void)fprintf(stdout, "%s%zu", i == 0 ? "" : ",", recognition.tasks[i]);
        }
        (void)fprintf(stdout, "\n");
        status = 0;
    } else {
        Location location;
        if (recognition.error_position < markup.count)
            location = markup.tokens[recognition.error_position].loc;
        else
            location = end_location(input_source, input_length);
        (void)fprintf(stdout, "REJECT offset=%zu line=%zu column=%zu expected=%s\n",
                      location.offset, location.line, location.column, recognition.expected);
        status = 1;
    }
    markup_free(&markup);
    grammar_free(&grammar);
    free(grammar_source);
    free(input_source);
    return status;
}
#include "grammar.h"

#include <stdlib.h>
#include <string.h>

typedef enum { G_EOF, G_IDENT, G_STRING, G_PERCENT, G_ASSIGN, G_PIPE, G_SEMI,
               G_DOLLAR, G_BAD } GTokenKind;

typedef struct {
    GTokenKind kind;
    char *text;
    Location loc;
} GrammarToken;

typedef struct {
    const char *source;
    size_t length;
    size_t pos;
    Location loc;
    Diagnostic *diagnostic;
} GrammarLexer;

typedef struct {
    GrammarLexer lexer;
    GrammarToken current;
    Grammar *grammar;
    Diagnostic *diagnostic;
} GrammarParser;

static char *copy_text(const char *text, size_t length)
{
    char *result = (char *)malloc(length + 1);
    if (result != NULL) {
        memcpy(result, text, length);
        result[length] = '\0';
    }
    return result;
}

static void grammar_token_free(GrammarToken *token)
{
    free(token->text);
    token->text = NULL;
}

static void advance_location(GrammarLexer *lexer, char c)
{
    lexer->pos++;
    if (c == '\n') {
        lexer->loc.line++;
        lexer->loc.column = 1;
    } else {
        lexer->loc.column++;
    }
}

static void lex_error(GrammarLexer *lexer, Location loc, const char *message)
{
    if (!lexer->diagnostic->present)
        diagnostic_set(lexer->diagnostic, loc, message);
}

static GrammarToken grammar_next(GrammarLexer *lexer)
{
    GrammarToken token;
    size_t start;
    size_t out;
    token.kind = G_EOF;
    token.text = NULL;
    token.loc = lexer->loc;
    while (lexer->pos < lexer->length) {
        char c = lexer->source[lexer->pos];
        if (c == ' ' || c == '\t' || c == '\r' || c == '\n') {
            advance_location(lexer, c);
        } else if (c == '#') {
            while (lexer->pos < lexer->length && lexer->source[lexer->pos] != '\n')
                advance_location(lexer, lexer->source[lexer->pos]);
        } else {
            break;
        }
    }
    token.loc = lexer->loc;
    if (lexer->pos == lexer->length)
        return token;
    start = lexer->pos;
    if ((lexer->source[lexer->pos] >= 'A' && lexer->source[lexer->pos] <= 'Z') ||
        (lexer->source[lexer->pos] >= 'a' && lexer->source[lexer->pos] <= 'z') ||
        lexer->source[lexer->pos] == '_') {
        advance_location(lexer, lexer->source[lexer->pos]);
        while (lexer->pos < lexer->length) {
            char c = lexer->source[lexer->pos];
            if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
                  (c >= '0' && c <= '9') || c == '_'))
                break;
            advance_location(lexer, c);
        }
        token.kind = G_IDENT;
        token.text = copy_text(lexer->source + start, lexer->pos - start);
        if (token.text == NULL)
            lex_error(lexer, token.loc, "out of memory");
        return token;
    }
    if (lexer->source[lexer->pos] == '%') {
        advance_location(lexer, '%');
        start = lexer->pos;
        while (lexer->pos < lexer->length) {
            char c = lexer->source[lexer->pos];
            if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c == '_'))
                break;
            advance_location(lexer, c);
        }
        if (start == lexer->pos) {
            lex_error(lexer, token.loc, "expected directive name");
            token.kind = G_BAD;
            return token;
        }
        token.kind = G_PERCENT;
        token.text = copy_text(lexer->source + start, lexer->pos - start);
        if (token.text == NULL)
            lex_error(lexer, token.loc, "out of memory");
        return token;
    }
    if (lexer->source[lexer->pos] == '\'') {
        advance_location(lexer, '\'');
        out = 0;
        token.text = (char *)malloc(1);
        if (token.text == NULL) {
            lex_error(lexer, token.loc, "out of memory");
            token.kind = G_BAD;
            return token;
        }
        token.text[0] = '\0';
        while (lexer->pos < lexer->length && lexer->source[lexer->pos] != '\'') {
            char c = lexer->source[lexer->pos];
            if (c == '\\') {
                advance_location(lexer, c);
                if (lexer->pos == lexer->length ||
                    (lexer->source[lexer->pos] != '\'' && lexer->source[lexer->pos] != '\\')) {
                    lex_error(lexer, lexer->loc, "unsupported string escape");
                    grammar_token_free(&token);
                    token.kind = G_BAD;
                    return token;
                }
                c = lexer->source[lexer->pos];
            }
            {
                char *grown = (char *)realloc(token.text, out + 2);
                if (grown == NULL) {
                    lex_error(lexer, token.loc, "out of memory");
                    grammar_token_free(&token);
                    token.kind = G_BAD;
                    return token;
                }
                token.text = grown;
            }
            token.text[out++] = c;
            token.text[out] = '\0';
            advance_location(lexer, c);
        }
        if (lexer->pos == lexer->length) {
            lex_error(lexer, token.loc, "unterminated grammar string");
            grammar_token_free(&token);
            token.kind = G_BAD;
            return token;
        }
        advance_location(lexer, '\'');
        token.kind = G_STRING;
        return token;
    }
    advance_location(lexer, lexer->source[lexer->pos]);
    switch (lexer->source[start]) {
    case ':':
        if (lexer->pos + 1 < lexer->length && lexer->source[lexer->pos] == ':' &&
            lexer->source[lexer->pos + 1] == '=') {
            advance_location(lexer, ':');
            advance_location(lexer, '=');
            token.kind = G_ASSIGN;
        } else {
            token.kind = G_BAD;
            lex_error(lexer, token.loc, "expected ::= operator");
        }
        break;
    case '|': token.kind = G_PIPE; break;
    case ';': token.kind = G_SEMI; break;
    case '$': token.kind = G_DOLLAR; break;
    default:
        token.kind = G_BAD;
        lex_error(lexer, token.loc, "invalid grammar character");
        break;
    }
    return token;
}

static int parser_advance(GrammarParser *parser)
{
    grammar_token_free(&parser->current);
    parser->current = grammar_next(&parser->lexer);
    return parser->diagnostic->present ? -1 : 0;
}

static void parse_error(GrammarParser *parser, const char *message)
{
    if (!parser->diagnostic->present)
        diagnostic_set(parser->diagnostic, parser->current.loc, message);
}

static int grow_array(void **data, size_t *capacity, size_t item_size, size_t needed)
{
    size_t next = *capacity == 0 ? 4 : *capacity;
    void *grown;
    while (next < needed) {
        if (next > ((size_t)-1) / 2)
            return -1;
        next *= 2;
    }
    grown = realloc(*data, next * item_size);
    if (grown == NULL)
        return -1;
    *data = grown;
    *capacity = next;
    return 0;
}

static int append_rule(Grammar *grammar, Rule **out)
{
    if (grow_array((void **)&grammar->rules, &grammar->rule_capacity, sizeof(*grammar->rules),
                   grammar->rule_count + 1) != 0)
        return -1;
    *out = &grammar->rules[grammar->rule_count++];
    memset(*out, 0, sizeof(**out));
    return 0;
}

static int append_alternative(Rule *rule, Alternative **out)
{
    if (grow_array((void **)&rule->alternatives, &rule->capacity, sizeof(*rule->alternatives),
                   rule->count + 1) != 0)
        return -1;
    *out = &rule->alternatives[rule->count++];
    memset(*out, 0, sizeof(**out));
    return 0;
}

static int append_symbol(Alternative *alternative, GrammarSymbol symbol)
{
    if (grow_array((void **)&alternative->symbols, &alternative->capacity, sizeof(*alternative->symbols),
                   alternative->count + 1) != 0)
        return -1;
    alternative->symbols[alternative->count++] = symbol;
    return 0;
}

static size_t find_rule(const Grammar *grammar, const char *name)
{
    size_t i;
    for (i = 0; i < grammar->rule_count; i++)
        if (strcmp(grammar->rules[i].name, name) == 0)
            return i;
    return (size_t)-1;
}

static int token_kind_from_name(const char *name, GrammarTokenKind *kind)
{
    if (strcmp(name, "IDENT") == 0) *kind = TOK_IDENT;
    else if (strcmp(name, "STRING") == 0) *kind = TOK_STRING;
    else if (strcmp(name, "TEXT") == 0) *kind = TOK_TEXT;
    else return -1;
    return 0;
}

static int parse_directives(GrammarParser *parser)
{
    if (parser->current.kind != G_PERCENT || strcmp(parser->current.text, "start") != 0) {
        parse_error(parser, "first directive must be %start NAME");
        return -1;
    }
    if (parser_advance(parser) != 0 || parser->current.kind != G_IDENT) {
        parse_error(parser, "expected start rule name");
        return -1;
    }
    parser->grammar->start_name = copy_text(parser->current.text, strlen(parser->current.text));
    if (parser->grammar->start_name == NULL) {
        parse_error(parser, "out of memory");
        return -1;
    }
    if (parser_advance(parser) != 0)
        return -1;
    while (parser->current.kind == G_PERCENT) {
        GrammarTokenKind kind;
        if (strcmp(parser->current.text, "token") != 0) {
            parse_error(parser, "unknown directive");
            return -1;
        }
        if (parser_advance(parser) != 0 || parser->current.kind != G_IDENT) {
            parse_error(parser, "expected token kind");
            return -1;
        }
        if (token_kind_from_name(parser->current.text, &kind) != 0) {
            parse_error(parser, "token kind must be IDENT, STRING, or TEXT");
            return -1;
        }
        if (parser->grammar->declared_tokens[kind]) {
            parse_error(parser, "duplicate token declaration");
            return -1;
        }
        parser->grammar->declared_tokens[kind] = 1;
        if (parser_advance(parser) != 0)
            return -1;
    }
    return 0;
}

static int parse_rules(GrammarParser *parser)
{
    while (parser->current.kind == G_IDENT) {
        Rule *rule;
        if (find_rule(parser->grammar, parser->current.text) != (size_t)-1) {
            parse_error(parser, "duplicate rule");
            return -1;
        }
        if (append_rule(parser->grammar, &rule) != 0) {
            parse_error(parser, "out of memory");
            return -1;
        }
        rule->name = copy_text(parser->current.text, strlen(parser->current.text));
        if (rule->name == NULL) {
            parse_error(parser, "out of memory");
            return -1;
        }
        if (parser_advance(parser) != 0 || parser->current.kind != G_ASSIGN) {
            parse_error(parser, "expected ::= after rule name");
            return -1;
        }
        if (parser_advance(parser) != 0)
            return -1;
        for (;;) {
            Alternative *alternative;
            if (append_alternative(rule, &alternative) != 0) {
                parse_error(parser, "out of memory");
                return -1;
            }
            while (parser->current.kind == G_IDENT || parser->current.kind == G_STRING ||
                   parser->current.kind == G_DOLLAR) {
                GrammarSymbol symbol;
                memset(&symbol, 0, sizeof(symbol));
                if (parser->current.kind == G_IDENT) {
                    symbol.kind = SYM_NONTERM;
                    symbol.text = copy_text(parser->current.text, strlen(parser->current.text));
                } else if (parser->current.kind == G_STRING) {
                    symbol.kind = SYM_LITERAL;
                    symbol.text = copy_text(parser->current.text, strlen(parser->current.text));
                } else {
                    GrammarTokenKind kind;
                    if (parser_advance(parser) != 0 || parser->current.kind != G_IDENT) {
                        parse_error(parser, "expected token kind after $");
                        return -1;
                    }
                    if (token_kind_from_name(parser->current.text, &kind) != 0 ||
                        !parser->grammar->declared_tokens[kind]) {
                        parse_error(parser, "$ reference uses an undeclared token kind");
                        return -1;
                    }
                    symbol.kind = SYM_TOKEN;
                    symbol.token_kind = kind;
                }
                if (symbol.kind != SYM_TOKEN && symbol.text == NULL) {
                    parse_error(parser, "out of memory");
                    return -1;
                }
                if (append_symbol(alternative, symbol) != 0) {
                    free(symbol.text);
                    parse_error(parser, "out of memory");
                    return -1;
                }
                if (parser_advance(parser) != 0)
                    return -1;
            }
            if (parser->current.kind == G_PIPE) {
                if (parser_advance(parser) != 0)
                    return -1;
                continue;
            }
            if (parser->current.kind != G_SEMI) {
                parse_error(parser, "expected | or ; in production");
                return -1;
            }
            if (parser_advance(parser) != 0)
                return -1;
            break;
        }
    }
    if (parser->grammar->rule_count == 0) {
        parse_error(parser, "grammar has no productions");
        return -1;
    }
    if (parser->current.kind != G_EOF) {
        parse_error(parser, "unexpected grammar input");
        return -1;
    }
    return 0;
}

static int validate_grammar(Grammar *grammar, Diagnostic *diagnostic)
{
    size_t i;
    size_t *nullable;
    unsigned char *edges;
    size_t *indegree;
    size_t *queue;
    int changed;
    if (find_rule(grammar, grammar->start_name) == (size_t)-1) {
        diagnostic_set(diagnostic, (Location){0, 1, 1}, "start rule is not defined");
        return -1;
    }
    grammar->start_rule = find_rule(grammar, grammar->start_name);
    for (i = 0; i < grammar->rule_count; i++) {
        size_t j;
        for (j = 0; j < grammar->rules[i].count; j++) {
            size_t k;
            Alternative *alt = &grammar->rules[i].alternatives[j];
            for (k = 0; k < alt->count; k++) {
                GrammarSymbol *symbol = &alt->symbols[k];
                if (symbol->kind == SYM_NONTERM && find_rule(grammar, symbol->text) == (size_t)-1) {
                    diagnostic_setf(diagnostic, (Location){0, 1, 1}, "undefined nonterminal: %s", symbol->text);
                    return -1;
                }
            }
        }
    }
    nullable = (size_t *)calloc(grammar->rule_count, sizeof(*nullable));
    edges = (unsigned char *)calloc(grammar->rule_count * grammar->rule_count, sizeof(*edges));
    indegree = (size_t *)calloc(grammar->rule_count, sizeof(*indegree));
    queue = (size_t *)calloc(grammar->rule_count, sizeof(*queue));
    if (nullable == NULL || edges == NULL || indegree == NULL || queue == NULL) {
        free(nullable); free(edges); free(indegree); free(queue);
        diagnostic_set(diagnostic, (Location){0, 1, 1}, "out of memory");
        return -1;
    }
    do {
        changed = 0;
        for (i = 0; i < grammar->rule_count; i++) {
            size_t j;
            for (j = 0; j < grammar->rules[i].count; j++) {
                size_t k;
                int can_empty = 1;
                Alternative *alt = &grammar->rules[i].alternatives[j];
                for (k = 0; k < alt->count; k++) {
                    if (alt->symbols[k].kind != SYM_NONTERM ||
                        !nullable[find_rule(grammar, alt->symbols[k].text)]) {
                        can_empty = 0;
                        break;
                    }
                }
                if (can_empty && !nullable[i]) {
                    nullable[i] = 1;
                    changed = 1;
                }
            }
        }
    } while (changed);
    for (i = 0; i < grammar->rule_count; i++) {
        size_t j;
        for (j = 0; j < grammar->rules[i].count; j++) {
            size_t k;
            Alternative *alt = &grammar->rules[i].alternatives[j];
            for (k = 0; k < alt->count; k++) {
                GrammarSymbol *symbol = &alt->symbols[k];
                if (symbol->kind != SYM_NONTERM)
                    break;
                edges[i * grammar->rule_count + find_rule(grammar, symbol->text)] = 1;
                if (!nullable[find_rule(grammar, symbol->text)])
                    break;
            }
        }
    }
    /* A topological traversal detects every cycle without a fixed rule-depth limit. */
    {
        size_t head = 0;
        size_t tail = 0;
        size_t removed = 0;
        size_t node;
        for (i = 0; i < grammar->rule_count; i++) {
            size_t target;
            for (target = 0; target < grammar->rule_count; target++)
                if (edges[i * grammar->rule_count + target])
                    indegree[target]++;
        }
        for (i = 0; i < grammar->rule_count; i++)
            if (indegree[i] == 0)
                queue[tail++] = i;
        while (head < tail) {
            node = queue[head++];
            removed++;
            for (i = 0; i < grammar->rule_count; i++) {
                if (edges[node * grammar->rule_count + i] && --indegree[i] == 0)
                    queue[tail++] = i;
            }
        }
        if (removed != grammar->rule_count) {
            for (i = 0; i < grammar->rule_count; i++)
                if (indegree[i] != 0)
                    break;
            diagnostic_setf(diagnostic, (Location){0, 1, 1}, "left recursion involving: %s",
                            grammar->rules[i].name);
            free(nullable); free(edges); free(indegree); free(queue);
            return -1;
        }
    }
    free(nullable); free(edges); free(indegree); free(queue);
    return 0;
}

int grammar_parse(const char *source, size_t length, Grammar *grammar, Diagnostic *diagnostic)
{
    GrammarParser parser;
    memset(grammar, 0, sizeof(*grammar));
    memset(diagnostic, 0, sizeof(*diagnostic));
    parser.lexer.source = source;
    parser.lexer.length = length;
    parser.lexer.pos = 0;
    parser.lexer.loc = (Location){0, 1, 1};
    parser.lexer.diagnostic = diagnostic;
    parser.current.kind = G_EOF;
    parser.current.text = NULL;
    parser.grammar = grammar;
    parser.diagnostic = diagnostic;
    parser_advance(&parser);
    if (!diagnostic->present && parse_directives(&parser) == 0 && parse_rules(&parser) == 0)
        (void)validate_grammar(grammar, diagnostic);
    grammar_token_free(&parser.current);
    if (diagnostic->present) {
        grammar_free(grammar);
        return -1;
    }
    return 0;
}

int grammar_set_start(Grammar *grammar, const char *name, Diagnostic *diagnostic)
{
    size_t index = find_rule(grammar, name);
    if (index == (size_t)-1) {
        diagnostic_setf(diagnostic, (Location){0, 1, 1}, "start override is not defined: %s", name);
        return -1;
    }
    free(grammar->start_name);
    grammar->start_name = copy_text(name, strlen(name));
    if (grammar->start_name == NULL) {
        diagnostic_set(diagnostic, (Location){0, 1, 1}, "out of memory");
        return -1;
    }
    grammar->start_rule = index;
    return 0;
}

void grammar_free(Grammar *grammar)
{
    size_t i;
    for (i = 0; i < grammar->rule_count; i++) {
        size_t j;
        Rule *rule = &grammar->rules[i];
        free(rule->name);
        for (j = 0; j < rule->count; j++) {
            size_t k;
            for (k = 0; k < rule->alternatives[j].count; k++)
                free(rule->alternatives[j].symbols[k].text);
            free(rule->alternatives[j].symbols);
        }
        free(rule->alternatives);
    }
    free(grammar->rules);
    free(grammar->start_name);
    memset(grammar, 0, sizeof(*grammar));
}
#include "markup.h"

#include <stdlib.h>
#include <string.h>

static char *copy_text(const char *text, size_t length)
{
    char *result = (char *)malloc(length + 1);
    if (result != NULL) {
        memcpy(result, text, length);
        result[length] = '\0';
    }
    return result;
}

static int grow_tokens(Markup *markup)
{
    size_t capacity = markup->capacity == 0 ? 16 : markup->capacity * 2;
    MarkupToken *grown;
    if (markup->capacity >= markup->count + 1)
        return 0;
    if (capacity < markup->count + 1)
        return -1;
    grown = (MarkupToken *)realloc(markup->tokens, capacity * sizeof(*grown));
    if (grown == NULL)
        return -1;
    markup->tokens = grown;
    markup->capacity = capacity;
    return 0;
}

static int add_token(Markup *markup, MarkupKind kind, const char *text, size_t length, Location loc)
{
    MarkupToken *token;
    if (grow_tokens(markup) != 0)
        return -1;
    token = &markup->tokens[markup->count++];
    token->kind = kind;
    token->lexeme = copy_text(text, length);
    token->loc = loc;
    if (token->lexeme == NULL) {
        markup->count--;
        return -1;
    }
    return 0;
}

static void move_location(Location *loc, char c, size_t *offset)
{
    (*offset)++;
    if (c == '\n') {
        loc->line++;
        loc->column = 1;
    } else {
        loc->column++;
    }
}

static int ascii_space(char c)
{
    return c == ' ' || c == '\t' || c == '\r' || c == '\n';
}

static int identifier_start(char c)
{
    return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c == '_' || c == ':';
}

static int identifier_part(char c)
{
    return identifier_start(c) || (c >= '0' && c <= '9') || c == '.' || c == '-';
}

int markup_lex(const char *source, size_t length, Markup *markup, Diagnostic *diagnostic)
{
    size_t offset = 0;
    Location loc = {0, 1, 1};
    int in_tag = 0;
    memset(markup, 0, sizeof(*markup));
    memset(diagnostic, 0, sizeof(*diagnostic));
    while (offset < length) {
        char c = source[offset];
        Location start = loc;
        size_t begin;
        if ((unsigned char)c < 0x20 && !ascii_space(c)) {
            diagnostic_set(diagnostic, loc, "invalid byte in markup");
            markup_free(markup);
            return -1;
        }
        if ((unsigned char)c >= 0x7f) {
            diagnostic_set(diagnostic, loc, "invalid byte in markup");
            markup_free(markup);
            return -1;
        }
        if (!in_tag) {
            if (c == '<') {
                if (add_token(markup, MARKUP_LITERAL, "<", 1, start) != 0)
                    goto out_of_memory;
                move_location(&loc, c, &offset);
                in_tag = 1;
            } else {
                begin = offset;
                {
                    int all_whitespace = 1;
                    while (offset < length && source[offset] != '<') {
                    c = source[offset];
                    if (((unsigned char)c < 0x20 && !ascii_space(c)) || (unsigned char)c >= 0x7f) {
                        diagnostic_set(diagnostic, loc, "invalid byte in markup");
                        markup_free(markup);
                        return -1;
                    }
                    if (!ascii_space(c))
                        all_whitespace = 0;
                    move_location(&loc, c, &offset);
                    }
                    if (!all_whitespace && add_token(markup, MARKUP_TEXT, source + begin,
                                                     offset - begin, start) != 0)
                        goto out_of_memory;
                }
            }
            continue;
        }
        if (ascii_space(c)) {
            move_location(&loc, c, &offset);
            continue;
        }
        if (c == '<' || c == '>' || c == '/' || c == '=') {
            if (add_token(markup, MARKUP_LITERAL, &c, 1, start) != 0)
                goto out_of_memory;
            move_location(&loc, c, &offset);
            if (c == '>')
                in_tag = 0;
            continue;
        }
        if (c == '\'' || c == '"') {
            char quote = c;
            size_t out = 0;
            char *value = (char *)malloc(1);
            if (value == NULL)
                goto out_of_memory;
            value[0] = '\0';
            move_location(&loc, c, &offset);
            while (offset < length && source[offset] != quote) {
                c = source[offset];
                if (c == '\\') {
                    move_location(&loc, c, &offset);
                    if (offset == length || (source[offset] != quote && source[offset] != '\\')) {
                        free(value);
                        diagnostic_set(diagnostic, loc, "invalid string escape in markup");
                        markup_free(markup);
                        return -1;
                    }
                    c = source[offset];
                }
                if ((unsigned char)c < 0x20 || (unsigned char)c >= 0x7f) {
                    free(value);
                    diagnostic_set(diagnostic, loc, "invalid byte in markup string");
                    markup_free(markup);
                    return -1;
                }
                {
                    char *grown = (char *)realloc(value, out + 2);
                    if (grown == NULL) {
                        free(value);
                        goto out_of_memory;
                    }
                    value = grown;
                }
                value[out++] = c;
                value[out] = '\0';
                move_location(&loc, c, &offset);
            }
            if (offset == length) {
                free(value);
                diagnostic_set(diagnostic, start, "unterminated markup string");
                markup_free(markup);
                return -1;
            }
            move_location(&loc, quote, &offset);
            if (grow_tokens(markup) != 0) {
                free(value);
                goto out_of_memory;
            }
            markup->tokens[markup->count++] = (MarkupToken){MARKUP_STRING, value, start};
            continue;
        }
        if (identifier_start(c)) {
            begin = offset;
            move_location(&loc, c, &offset);
            while (offset < length && identifier_part(source[offset]))
                move_location(&loc, source[offset], &offset);
            if (add_token(markup, MARKUP_IDENT, source + begin, offset - begin, start) != 0)
                goto out_of_memory;
            continue;
        }
        diagnostic_set(diagnostic, loc, "invalid character in markup tag");
        markup_free(markup);
        return -1;
    }
    if (in_tag) {
        diagnostic_set(diagnostic, loc, "unterminated markup tag");
        markup_free(markup);
        return -1;
    }
    return 0;

out_of_memory:
    diagnostic_set(diagnostic, loc, "out of memory");
    markup_free(markup);
    return -1;
}

void markup_free(Markup *markup)
{
    size_t i;
    for (i = 0; i < markup->count; i++)
        free(markup->tokens[i].lexeme);
    free(markup->tokens);
    memset(markup, 0, sizeof(*markup));
}
#include "recognizer.h"

#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    size_t rule;
    size_t alternative;
    size_t dot;
    size_t origin;
} ChartItem;

typedef struct {
    ChartItem *data;
    size_t count;
    size_t capacity;
} ItemVector;

typedef struct {
    ChartItem *data;
    size_t count;
    size_t capacity;
} CandidateVector;

typedef struct {
    const Grammar *grammar;
    ItemVector *charts;
    size_t position;
    CandidateVector *candidates;
    size_t *task_counts;
    atomic_int failed;
} ClosureWork;

typedef struct {
    const Grammar *grammar;
    const Markup *markup;
    const ItemVector *current;
    size_t position;
    CandidateVector *candidates;
    size_t *task_counts;
    atomic_int failed;
} ScanWork;

static int item_equal(const ChartItem *a, const ChartItem *b)
{
    return a->rule == b->rule && a->alternative == b->alternative &&
           a->dot == b->dot && a->origin == b->origin;
}

static int vector_grow(ChartItem **data, size_t *capacity, size_t needed)
{
    size_t next = *capacity == 0 ? 16 : *capacity * 2;
    ChartItem *grown;
    if (*capacity >= needed)
        return 0;
    while (next < needed) {
        if (next > ((size_t)-1) / 2)
            return -1;
        next *= 2;
    }
    grown = (ChartItem *)realloc(*data, next * sizeof(*grown));
    if (grown == NULL)
        return -1;
    *data = grown;
    *capacity = next;
    return 0;
}

static int add_item(ItemVector *vector, ChartItem item)
{
    size_t i;
    for (i = 0; i < vector->count; i++)
        if (item_equal(&vector->data[i], &item))
            return 0;
    if (vector_grow(&vector->data, &vector->capacity, vector->count + 1) != 0)
        return -1;
    vector->data[vector->count++] = item;
    return 1;
}

static int add_candidate(CandidateVector *vector, ChartItem item, atomic_int *failed)
{
    if (vector_grow(&vector->data, &vector->capacity, vector->count + 1) != 0) {
        atomic_store(failed, 1);
        return -1;
    }
    vector->data[vector->count++] = item;
    return 0;
}

static size_t rule_index(const Grammar *grammar, const char *name)
{
    size_t i;
    for (i = 0; i < grammar->rule_count; i++)
        if (strcmp(grammar->rules[i].name, name) == 0)
            return i;
    return (size_t)-1;
}

static const GrammarSymbol *next_symbol(const Grammar *grammar, const ChartItem *item)
{
    const Alternative *alternative = &grammar->rules[item->rule].alternatives[item->alternative];
    if (item->dot >= alternative->count)
        return NULL;
    return &alternative->symbols[item->dot];
}

static void closure_task(void *context, size_t worker, size_t begin, size_t end)
{
    ClosureWork *work = (ClosureWork *)context;
    ItemVector *current = &work->charts[work->position];
    CandidateVector *out = &work->candidates[worker];
    size_t i;
    if (begin < end)
        work->task_counts[worker]++;
    for (i = begin; i < end && !atomic_load(&work->failed); i++) {
        ChartItem item = current->data[i];
        const GrammarSymbol *symbol = next_symbol(work->grammar, &item);
        if (symbol != NULL && symbol->kind == SYM_NONTERM) {
            size_t target = rule_index(work->grammar, symbol->text);
            size_t j;
            for (j = 0; j < work->grammar->rules[target].count; j++) {
                ChartItem candidate = {target, j, 0, work->position};
                if (add_candidate(out, candidate, &work->failed) != 0)
                    return;
            }
            /* Prediction can follow an epsilon constituent already in this chart. */
            for (j = 0; j < current->count; j++) {
                ChartItem completed = current->data[j];
                if (completed.rule == target && completed.origin == work->position &&
                    next_symbol(work->grammar, &completed) == NULL) {
                    ChartItem candidate = {item.rule, item.alternative, item.dot + 1, item.origin};
                    if (add_candidate(out, candidate, &work->failed) != 0)
                        return;
                }
            }
        } else if (symbol == NULL) {
            size_t j;
            if (item.origin > work->position)
                continue;
            for (j = 0; j < work->charts[item.origin].count; j++) {
                ChartItem parent = work->charts[item.origin].data[j];
                const GrammarSymbol *wanted = next_symbol(work->grammar, &parent);
                if (wanted != NULL && wanted->kind == SYM_NONTERM &&
                    rule_index(work->grammar, wanted->text) == item.rule) {
                    ChartItem candidate = {parent.rule, parent.alternative, parent.dot + 1, parent.origin};
                    if (add_candidate(out, candidate, &work->failed) != 0)
                        return;
                }
            }
        }
    }
}

static int token_matches(const GrammarSymbol *symbol, const MarkupToken *token)
{
    if (symbol->kind == SYM_LITERAL)
        return strcmp(symbol->text, token->lexeme) == 0;
    if (symbol->kind == SYM_TOKEN) {
        if (symbol->token_kind == TOK_IDENT) return token->kind == MARKUP_IDENT;
        if (symbol->token_kind == TOK_STRING) return token->kind == MARKUP_STRING;
        return token->kind == MARKUP_TEXT;
    }
    return 0;
}

static void scan_task(void *context, size_t worker, size_t begin, size_t end)
{
    ScanWork *work = (ScanWork *)context;
    CandidateVector *out = &work->candidates[worker];
    size_t i;
    if (end > work->current->count)
        end = work->current->count;
    if (begin < end)
        work->task_counts[worker]++;
    for (i = begin; i < end && !atomic_load(&work->failed); i++) {
        const ChartItem *item = &work->current->data[i];
        const GrammarSymbol *symbol = next_symbol(work->grammar, item);
        if (symbol != NULL && symbol->kind != SYM_NONTERM &&
            token_matches(symbol, &work->markup->tokens[work->position])) {
            ChartItem candidate = {item->rule, item->alternative, item->dot + 1, item->origin};
            if (add_candidate(out, candidate, &work->failed) != 0)
                return;
        }
    }
}

static int candidate_compare(const void *left, const void *right)
{
    const ChartItem *a = (const ChartItem *)left;
    const ChartItem *b = (const ChartItem *)right;
    if (a->rule != b->rule) return a->rule < b->rule ? -1 : 1;
    if (a->alternative != b->alternative) return a->alternative < b->alternative ? -1 : 1;
    if (a->dot != b->dot) return a->dot < b->dot ? -1 : 1;
    if (a->origin != b->origin) return a->origin < b->origin ? -1 : 1;
    return 0;
}

static int merge_candidates(ItemVector *target, CandidateVector *vectors)
{
    size_t total = 0;
    size_t i;
    ChartItem *all;
    size_t at = 0;
    for (i = 0; i < 8; i++)
        total += vectors[i].count;
    if (total == 0)
        return 0;
    all = (ChartItem *)malloc(total * sizeof(*all));
    if (all == NULL)
        return -1;
    for (i = 0; i < 8; i++) {
        memcpy(all + at, vectors[i].data, vectors[i].count * sizeof(*all));
        at += vectors[i].count;
    }
    qsort(all, total, sizeof(*all), candidate_compare);
    for (i = 0; i < total; i++) {
        if (add_item(target, all[i]) < 0) {
            free(all);
            return -1;
        }
    }
    free(all);
    return 0;
}

static void clear_candidates(CandidateVector *vectors)
{
    size_t i;
    for (i = 0; i < 8; i++)
        vectors[i].count = 0;
}

static void free_candidates(CandidateVector *vectors)
{
    size_t i;
    for (i = 0; i < 8; i++)
        free(vectors[i].data);
}

static void free_charts(ItemVector *charts, size_t count)
{
    size_t i;
    for (i = 0; i < count; i++)
        free(charts[i].data);
    free(charts);
}

static void expected_append(char *expected, size_t capacity, const char *text)
{
    size_t used = strlen(expected);
    while (*text != '\0' && used + 1 < capacity)
        expected[used++] = *text++;
    expected[used] = '\0';
}

static void expected_append_literal(char *expected, size_t capacity, const char *text)
{
    char escaped[8];
    unsigned char c;
    expected_append(expected, capacity, "'");
    while (*text != '\0') {
        c = (unsigned char)*text++;
        if (c == '\n') expected_append(expected, capacity, "\\n");
        else if (c == '\r') expected_append(expected, capacity, "\\r");
        else if (c == '\t') expected_append(expected, capacity, "\\t");
        else if (c == '\\') expected_append(expected, capacity, "\\\\");
        else if (c == '\'') expected_append(expected, capacity, "\\'");
        else if (c < 0x20 || c >= 0x7f) {
            (void)snprintf(escaped, sizeof(escaped), "\\x%02X", (unsigned)c);
            expected_append(expected, capacity, escaped);
        } else {
            size_t used = strlen(expected);
            if (used + 1 < capacity) {
                expected[used] = (char)c;
                expected[used + 1] = '\0';
            }
        }
    }
    expected_append(expected, capacity, "'");
}

static void expected_add(char *expected, size_t capacity, const GrammarSymbol *symbol)
{
    if (expected[0] != '\0')
        expected_append(expected, capacity, ", ");
    if (symbol->kind == SYM_LITERAL)
        expected_append_literal(expected, capacity, symbol->text);
    else if (symbol->token_kind == TOK_IDENT)
        expected_append(expected, capacity, "$IDENT");
    else if (symbol->token_kind == TOK_STRING)
        expected_append(expected, capacity, "$STRING");
    else
        expected_append(expected, capacity, "$TEXT");
}

int recognize(const Grammar *grammar, const Markup *markup, Recognition *result)
{
    WorkerPool pool;
    ItemVector *charts;
    CandidateVector candidates[8];
    size_t chart_count = markup->count + 1;
    size_t position;
    int pool_ok = 0;
    memset(result, 0, sizeof(*result));
    memset(&pool, 0, sizeof(pool));
    memset(candidates, 0, sizeof(candidates));
    charts = (ItemVector *)calloc(chart_count, sizeof(*charts));
    if (charts == NULL)
        return -1;
    if (pool_start(&pool) != 0) {
        free_charts(charts, chart_count);
        return -1;
    }
    pool_ok = 1;
    for (position = 0; position < grammar->rules[grammar->start_rule].count; position++) {
        ChartItem seed = {grammar->start_rule, position, 0, 0};
        if (add_item(&charts[0], seed) < 0)
            goto failed;
    }
    for (position = 0; position <= markup->count; position++) {
        size_t processed = 0;
        while (processed < charts[position].count) {
            ClosureWork work;
            size_t snapshot = charts[position].count;
            clear_candidates(candidates);
            work.grammar = grammar;
            work.charts = charts;
            work.position = position;
            work.candidates = candidates;
            work.task_counts = result->tasks;
            atomic_init(&work.failed, 0);
            if (pool_run_range(&pool, processed, snapshot, closure_task, &work) != 0 ||
                atomic_load(&work.failed))
                goto failed;
            result->rounds++;
            if (merge_candidates(&charts[position], candidates) != 0)
                goto failed;
            processed = snapshot;
        }
        if (position < markup->count) {
            ScanWork work;
            clear_candidates(candidates);
            work.grammar = grammar;
            work.markup = markup;
            work.current = &charts[position];
            work.position = position;
            work.candidates = candidates;
            work.task_counts = result->tasks;
            atomic_init(&work.failed, 0);
            if (pool_run_range(&pool, 0, charts[position].count, scan_task, &work) != 0 ||
                atomic_load(&work.failed))
                goto failed;
            result->rounds++;
            if (merge_candidates(&charts[position + 1], candidates) != 0)
                goto failed;
        }
    }
    result->accepted = 0;
    {
        size_t i;
        for (i = 0; i < charts[markup->count].count; i++) {
            ChartItem item = charts[markup->count].data[i];
            if (item.rule == grammar->start_rule && item.origin == 0 &&
                next_symbol(grammar, &item) == NULL) {
                result->accepted = 1;
                break;
            }
        }
    }
    if (!result->accepted) {
        size_t furthest = 0;
        for (position = 0; position <= markup->count; position++) {
            size_t i;
            int active = 0;
            for (i = 0; i < charts[position].count; i++)
                if (next_symbol(grammar, &charts[position].data[i]) != NULL)
                    active = 1;
            if (active)
                furthest = position;
        }
        result->error_position = furthest;
        result->expected[0] = '\0';
        for (position = 0; position < charts[furthest].count; position++) {
            const GrammarSymbol *symbol = next_symbol(grammar, &charts[furthest].data[position]);
            if (symbol != NULL && symbol->kind != SYM_NONTERM)
                expected_add(result->expected, sizeof(result->expected), symbol);
        }
        if (result->expected[0] == '\0')
            (void)snprintf(result->expected, sizeof(result->expected), "markup token");
    }
    free_candidates(candidates);
    if (pool_ok)
        pool_stop(&pool);
    free_charts(charts, chart_count);
    return 0;

failed:
    free_candidates(candidates);
    if (pool_ok)
        pool_stop(&pool);
    free_charts(charts, chart_count);
    return -1;
}
#include "pool.h"

#include <stdlib.h>

static void *worker_main(void *arg)
{
    PoolWorkerArg *worker = (PoolWorkerArg *)arg;
    WorkerPool *pool = worker->pool;
    size_t index = worker->index;
    unsigned long seen = 0;

    for (;;) {
        pthread_mutex_lock(&pool->mutex);
        while (!pool->stopping && seen == pool->generation)
            pthread_cond_wait(&pool->work_ready, &pool->mutex);
        if (pool->stopping) {
            pthread_mutex_unlock(&pool->mutex);
            return NULL;
        }
        seen = pool->generation;
        pthread_mutex_unlock(&pool->mutex);

        if (pool->task != NULL && pool->ends[index] > pool->begins[index])
            pool->task(pool->context, index, pool->begins[index], pool->ends[index]);

        pthread_mutex_lock(&pool->mutex);
        pool->completed++;
        if (pool->completed == 8)
            pthread_cond_signal(&pool->done);
        pthread_mutex_unlock(&pool->mutex);
    }
}

int pool_start(WorkerPool *pool)
{
    size_t i;
    pool->generation = 0;
    pool->stopping = 0;
    pool->task_count = 0;
    pool->completed = 0;
    pool->task = NULL;
    pool->context = NULL;
    pool->begins = (size_t *)calloc(8, sizeof(*pool->begins));
    pool->ends = (size_t *)calloc(8, sizeof(*pool->ends));
    if (pool->begins == NULL || pool->ends == NULL) {
        free(pool->begins);
        free(pool->ends);
        return -1;
    }
    if (pthread_mutex_init(&pool->mutex, NULL) != 0)
        goto fail_arrays;
    if (pthread_cond_init(&pool->work_ready, NULL) != 0)
        goto fail_mutex;
    if (pthread_cond_init(&pool->done, NULL) != 0)
        goto fail_work;
    pool->initialized = 1;
    for (i = 0; i < 8; i++) {
        pool->worker_args[i].pool = pool;
        pool->worker_args[i].index = i;
        if (pthread_create(&pool->threads[i], NULL, worker_main, &pool->worker_args[i]) != 0) {
            size_t j;
            pthread_mutex_lock(&pool->mutex);
            pool->stopping = 1;
            pthread_cond_broadcast(&pool->work_ready);
            pthread_mutex_unlock(&pool->mutex);
            for (j = 0; j < i; j++)
                pthread_join(pool->threads[j], NULL);
            pthread_cond_destroy(&pool->done);
            pthread_cond_destroy(&pool->work_ready);
            pthread_mutex_destroy(&pool->mutex);
            pool->initialized = 0;
            goto fail_arrays;
        }
    }
    return 0;

fail_work:
    pthread_cond_destroy(&pool->work_ready);
fail_mutex:
    pthread_mutex_destroy(&pool->mutex);
fail_arrays:
    free(pool->begins);
    free(pool->ends);
    pool->begins = NULL;
    pool->ends = NULL;
    return -1;
}

int pool_run(WorkerPool *pool, size_t count, PoolTask task, void *context)
{
    return pool_run_range(pool, 0, count, task, context);
}

int pool_run_range(WorkerPool *pool, size_t begin, size_t end, PoolTask task, void *context)
{
    size_t i;
    size_t span = end - begin;
    pthread_mutex_lock(&pool->mutex);
    pool->task_count = span;
    pool->task = task;
    pool->context = context;
    pool->completed = 0;
    for (i = 0; i < 8; i++) {
        pool->begins[i] = begin + (span * i) / 8;
        pool->ends[i] = begin + (span * (i + 1)) / 8;
    }
    pool->generation++;
    pthread_cond_broadcast(&pool->work_ready);
    while (pool->completed != 8)
        pthread_cond_wait(&pool->done, &pool->mutex);
    pthread_mutex_unlock(&pool->mutex);
    return 0;
}

void pool_stop(WorkerPool *pool)
{
    size_t i;
    if (!pool->initialized)
        return;
    pthread_mutex_lock(&pool->mutex);
    pool->stopping = 1;
    pthread_cond_broadcast(&pool->work_ready);
    pthread_mutex_unlock(&pool->mutex);
    for (i = 0; i < 8; i++)
        pthread_join(pool->threads[i], NULL);
    pthread_cond_destroy(&pool->done);
    pthread_cond_destroy(&pool->work_ready);
    pthread_mutex_destroy(&pool->mutex);
    free(pool->begins);
    free(pool->ends);
    pool->begins = NULL;
    pool->ends = NULL;
    pool->initialized = 0;
}

