    74	int markup_lex(const char *source, size_t length, Markup *markup, Diagnostic *diagnostic)
    75	{
    76	    size_t offset = 0;
    77	    Location loc = {0, 1, 1};
    78	    int in_tag = 0;
    79	    memset(markup, 0, sizeof(*markup));
    80	    memset(diagnostic, 0, sizeof(*diagnostic));
    81	    while (offset < length) {
    82	        char c = source[offset];
    83	        Location start = loc;
    84	        size_t begin;
    85	        if ((unsigned char)c < 0x20 && !ascii_space(c)) {
    86	            diagnostic_set(diagnostic, loc, "invalid byte in markup");
    87	            markup_free(markup);
    88	            return -1;
    89	        }
    90	        if ((unsigned char)c >= 0x7f) {
    91	            diagnostic_set(diagnostic, loc, "invalid byte in markup");
    92	            markup_free(markup);
    93	            return -1;
    94	        }
    95	        if (!in_tag) {
    96	            if (c == '<') {
    97	                if (add_token(markup, MARKUP_LITERAL, "<", 1, start) != 0)
    98	                    goto out_of_memory;
    99	                move_location(&loc, c, &offset);
   100	                in_tag = 1;
   101	            } else {
   102	                begin = offset;
   103	                {
   104	                    int all_whitespace = 1;
   105	                    while (offset < length && source[offset] != '<') {
   106	                    c = source[offset];
   107	                    if (((unsigned char)c < 0x20 && !ascii_space(c)) || (unsigned char)c >= 0x7f) {
   108	                        diagnostic_set(diagnostic, loc, "invalid byte in markup");
   109	                        markup_free(markup);
   110	                        return -1;
   111	                    }
   112	                    if (!ascii_space(c))
   113	                        all_whitespace = 0;
   114	                    move_location(&loc, c, &offset);
   115	                    }
   116	                    if (!all_whitespace && add_token(markup, MARKUP_TEXT, source + begin,
   117	                                                     offset - begin, start) != 0)
   118	                        goto out_of_memory;
   119	                }
   120	            }
   121	            continue;
   122	        }
   123	        if (ascii_space(c)) {
   124	            move_location(&loc, c, &offset);
   125	            continue;
   126	        }
   127	        if (c == '<' || c == '>' || c == '/' || c == '=') {
   128	            if (add_token(markup, MARKUP_LITERAL, &c, 1, start) != 0)
   129	                goto out_of_memory;
   130	            move_location(&loc, c, &offset);
   131	            if (c == '>')
   132	                in_tag = 0;
   133	            continue;
   134	        }
   135	        if (c == '\'' || c == '"') {
   136	            char quote = c;
   137	            size_t out = 0;
   138	            char *value = (char *)malloc(1);
   139	            if (value == NULL)
   140	                goto out_of_memory;
   141	            value[0] = '\0';
   142	            move_location(&loc, c, &offset);
   143	            while (offset < length && source[offset] != quote) {
   144	                c = source[offset];
   145	                if (c == '\\') {
   146	                    move_location(&loc, c, &offset);
   147	                    if (offset == length || (source[offset] != quote && source[offset] != '\\')) {
   148	                        free(value);
   149	                        diagnostic_set(diagnostic, loc, "invalid string escape in markup");
   150	                        markup_free(markup);
   151	                        return -1;
   152	                    }
   153	                    c = source[offset];
   154	                }
   155	                if ((unsigned char)c < 0x20 || (unsigned char)c >= 0x7f) {
   156	                    free(value);
   157	                    diagnostic_set(diagnostic, loc, "invalid byte in markup string");
   158	                    markup_free(markup);
   159	                    return -1;
   160	                }
   161	                {
   162	                    char *grown = (char *)realloc(value, out + 2);
   163	                    if (grown == NULL) {
   164	                        free(value);
   165	                        goto out_of_memory;
   166	                    }
   167	                    value = grown;
   168	                }
   169	                value[out++] = c;
   170	                value[out] = '\0';
   171	                move_location(&loc, c, &offset);
   172	            }
   173	            if (offset == length) {
   174	                free(value);
   175	                diagnostic_set(diagnostic, start, "unterminated markup string");
   176	                markup_free(markup);
   177	                return -1;
   178	            }
   179	            move_location(&loc, quote, &offset);
   180	            if (grow_tokens(markup) != 0) {
   181	                free(value);
   182	                goto out_of_memory;
   183	            }
   184	            markup->tokens[markup->count++] = (MarkupToken){MARKUP_STRING, value, start};
   185	            continue;
   186	        }
   187	        if (identifier_start(c)) {
   188	            begin = offset;
   189	            move_location(&loc, c, &offset);
   190	            while (offset < length && identifier_part(source[offset]))
   191	                move_location(&loc, source[offset], &offset);
   192	            if (add_token(markup, MARKUP_IDENT, source + begin, offset - begin, start) != 0)
   193	                goto out_of_memory;
   194	            continue;
   195	        }
   196	        diagnostic_set(diagnostic, loc, "invalid character in markup tag");
   197	        markup_free(markup);
   198	        return -1;
   199	    }
   200	    if (in_tag) {
   201	        diagnostic_set(diagnostic, loc, "unterminated markup tag");
   202	        markup_free(markup);
   203	        return -1;
   204	    }
   205	    return 0;
   206	
   207	out_of_memory:
   208	    diagnostic_set(diagnostic, loc, "out of memory");
   209	    markup_free(markup);
   210	    return -1;
   211	}
