   110	static void closure_task(void *context, size_t worker, size_t begin, size_t end)
   111	{
   112	    ClosureWork *work = (ClosureWork *)context;
   113	    ItemVector *current = &work->charts[work->position];
   114	    CandidateVector *out = &work->candidates[worker];
   115	    size_t i;
   116	    if (begin < end)
   117	        work->task_counts[worker]++;
   118	    for (i = begin; i < end && !atomic_load(&work->failed); i++) {
   119	        ChartItem item = current->data[i];
   120	        const GrammarSymbol *symbol = next_symbol(work->grammar, &item);
   121	        if (symbol != NULL && symbol->kind == SYM_NONTERM) {
   122	            size_t target = rule_index(work->grammar, symbol->text);
   123	            size_t j;
   124	            for (j = 0; j < work->grammar->rules[target].count; j++) {
   125	                ChartItem candidate = {target, j, 0, work->position};
   126	                if (add_candidate(out, candidate, &work->failed) != 0)
   127	                    return;
   128	            }
   129	            /* Prediction can follow an epsilon constituent already in this chart. */
   130	            for (j = 0; j < current->count; j++) {
   131	                ChartItem completed = current->data[j];
   132	                if (completed.rule == target && completed.origin == work->position &&
   133	                    next_symbol(work->grammar, &completed) == NULL) {
   134	                    ChartItem candidate = {item.rule, item.alternative, item.dot + 1, item.origin};
   135	                    if (add_candidate(out, candidate, &work->failed) != 0)
   136	                        return;
   137	                }
   138	            }
   139	        } else if (symbol == NULL) {
   140	            size_t j;
   141	            if (item.origin > work->position)
   142	                continue;
   143	            for (j = 0; j < work->charts[item.origin].count; j++) {
   144	                ChartItem parent = work->charts[item.origin].data[j];
   145	                const GrammarSymbol *wanted = next_symbol(work->grammar, &parent);
   146	                if (wanted != NULL && wanted->kind == SYM_NONTERM &&
   147	                    rule_index(work->grammar, wanted->text) == item.rule) {
   148	                    ChartItem candidate = {parent.rule, parent.alternative, parent.dot + 1, parent.origin};
   149	                    if (add_candidate(out, candidate, &work->failed) != 0)
   150	                        return;
   151	                }
   152	            }
   153	        }
   154	    }
   155	}
