   157	static int token_matches(const GrammarSymbol *symbol, const MarkupToken *token)
   158	{
   159	    if (symbol->kind == SYM_LITERAL)
   160	        return strcmp(symbol->text, token->lexeme) == 0;
   161	    if (symbol->kind == SYM_TOKEN) {
   162	        if (symbol->token_kind == TOK_IDENT) return token->kind == MARKUP_IDENT;
   163	        if (symbol->token_kind == TOK_STRING) return token->kind == MARKUP_STRING;
   164	        return token->kind == MARKUP_TEXT;
   165	    }
   166	    return 0;
   167	}
