   251	static void expected_append(char *expected, size_t capacity, const char *text)
   252	{
   253	    size_t used = strlen(expected);
   254	    while (*text != '\0' && used + 1 < capacity)
   255	        expected[used++] = *text++;
   256	    expected[used] = '\0';
   257	}
   258	
   259	static void expected_append_literal(char *expected, size_t capacity, const char *text)
   260	{
   261	    char escaped[8];
   262	    unsigned char c;
   263	    expected_append(expected, capacity, "'");
   264	    while (*text != '\0') {
   265	        c = (unsigned char)*text++;
   266	        if (c == '\n') expected_append(expected, capacity, "\\n");
   267	        else if (c == '\r') expected_append(expected, capacity, "\\r");
   268	        else if (c == '\t') expected_append(expected, capacity, "\\t");
   269	        else if (c == '\\') expected_append(expected, capacity, "\\\\");
   270	        else if (c == '\'') expected_append(expected, capacity, "\\'");
   271	        else if (c < 0x20 || c >= 0x7f) {
   272	            (void)snprintf(escaped, sizeof(escaped), "\\x%02X", (unsigned)c);
   273	            expected_append(expected, capacity, escaped);
   274	        } else {
   275	            size_t used = strlen(expected);
   276	            if (used + 1 < capacity) {
   277	                expected[used] = (char)c;
   278	                expected[used + 1] = '\0';
   279	            }
   280	        }
   281	    }
   282	    expected_append(expected, capacity, "'");
   283	}
   284	
   285	static void expected_add(char *expected, size_t capacity, const GrammarSymbol *symbol)
   286	{
   287	    if (expected[0] != '\0')
   288	        expected_append(expected, capacity, ", ");
   289	    if (symbol->kind == SYM_LITERAL)
   290	        expected_append_literal(expected, capacity, symbol->text);
   291	    else if (symbol->token_kind == TOK_IDENT)
   292	        expected_append(expected, capacity, "$IDENT");
   293	    else if (symbol->token_kind == TOK_STRING)
   294	        expected_append(expected, capacity, "$STRING");
   295	    else
   296	        expected_append(expected, capacity, "$TEXT");
   297	}
