   299	int recognize(const Grammar *grammar, const Markup *markup, Recognition *result)
   300	{
   301	    WorkerPool pool;
   302	    ItemVector *charts;
   303	    CandidateVector candidates[8];
   304	    size_t chart_count = markup->count + 1;
   305	    size_t position;
   306	    int pool_ok = 0;
   307	    memset(result, 0, sizeof(*result));
   308	    memset(&pool, 0, sizeof(pool));
   309	    memset(candidates, 0, sizeof(candidates));
   310	    charts = (ItemVector *)calloc(chart_count, sizeof(*charts));
   311	    if (charts == NULL)
   312	        return -1;
   313	    if (pool_start(&pool) != 0) {
   314	        free_charts(charts, chart_count);
   315	        return -1;
   316	    }
   317	    pool_ok = 1;
   318	    for (position = 0; position < grammar->rules[grammar->start_rule].count; position++) {
   319	        ChartItem seed = {grammar->start_rule, position, 0, 0};
   320	        if (add_item(&charts[0], seed) < 0)
   321	            goto failed;
   322	    }
   323	    for (position = 0; position <= markup->count; position++) {
   324	        size_t processed = 0;
   325	        while (processed < charts[position].count) {
   326	            ClosureWork work;
   327	            size_t snapshot = charts[position].count;
   328	            clear_candidates(candidates);
   329	            work.grammar = grammar;
   330	            work.charts = charts;
   331	            work.position = position;
   332	            work.candidates = candidates;
   333	            work.task_counts = result->tasks;
   334	            atomic_init(&work.failed, 0);
   335	            if (pool_run_range(&pool, processed, snapshot, closure_task, &work) != 0 ||
   336	                atomic_load(&work.failed))
   337	                goto failed;
   338	            result->rounds++;
   339	            if (merge_candidates(&charts[position], candidates) != 0)
   340	                goto failed;
   341	            processed = snapshot;
   342	        }
   343	        if (position < markup->count) {
   344	            ScanWork work;
   345	            clear_candidates(candidates);
   346	            work.grammar = grammar;
   347	            work.markup = markup;
   348	            work.current = &charts[position];
   349	            work.position = position;
   350	            work.candidates = candidates;
   351	            work.task_counts = result->tasks;
   352	            atomic_init(&work.failed, 0);
   353	            if (pool_run_range(&pool, 0, charts[position].count, scan_task, &work) != 0 ||
   354	                atomic_load(&work.failed))
   355	                goto failed;
   356	            result->rounds++;
   357	            if (merge_candidates(&charts[position + 1], candidates) != 0)
   358	                goto failed;
   359	        }
   360	    }
   361	    result->accepted = 0;
   362	    {
   363	        size_t i;
   364	        for (i = 0; i < charts[markup->count].count; i++) {
   365	            ChartItem item = charts[markup->count].data[i];
   366	            if (item.rule == grammar->start_rule && item.origin == 0 &&
   367	                next_symbol(grammar, &item) == NULL) {
   368	                result->accepted = 1;
   369	                break;
   370	            }
   371	        }
   372	    }
   373	    if (!result->accepted) {
   374	        size_t furthest = 0;
   375	        for (position = 0; position <= markup->count; position++) {
   376	            size_t i;
   377	            int active = 0;
   378	            for (i = 0; i < charts[position].count; i++)
   379	                if (next_symbol(grammar, &charts[position].data[i]) != NULL)
   380	                    active = 1;
   381	            if (active)
   382	                furthest = position;
   383	        }
   384	        result->error_position = furthest;
   385	        result->expected[0] = '\0';
   386	        for (position = 0; position < charts[furthest].count; position++) {
   387	            const GrammarSymbol *symbol = next_symbol(grammar, &charts[furthest].data[position]);
   388	            if (symbol != NULL && symbol->kind != SYM_NONTERM)
   389	                expected_add(result->expected, sizeof(result->expected), symbol);
   390	        }
   391	        if (result->expected[0] == '\0')
   392	            (void)snprintf(result->expected, sizeof(result->expected), "markup token");
   393	    }
   394	    free_candidates(candidates);
   395	    if (pool_ok)
   396	        pool_stop(&pool);
   397	    free_charts(charts, chart_count);
   398	    return 0;
   399	
   400	failed:
   401	    free_candidates(candidates);
   402	    if (pool_ok)
   403	        pool_stop(&pool);
   404	    free_charts(charts, chart_count);
   405	    return -1;
   406	}
